pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the from address and a dynamic list length and a value; the adversarial callee will accept the low-level calls
    function testFuzz_property(address from, uint256 v, uint8 tosLen) public {
        // keep tosLen reasonably bounded but allow zero to be filtered by vm.assume
        uint8 len = tosLen % 10; // keep array length small for gas but still variable
        vm.assume(len > 0);

        // prepare an array of recipient addresses: use freshly deployed AcceptAll contracts as callees
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            AcceptAll a = new AcceptAll();
            tos[i] = address(a);
        }

        // Call transfer and capture its returned boolean via try/catch to observe behavior
        bool ok;
        try c.transfer(from, tos[0], tos, v) returns (bool ret) {
            // if call returns, mark ok true and assert that return value is true
            ok = ret;
        } catch {
            // if it reverts, set ok to false (but reference C should only revert when tos.length==0, which we excluded)
            ok = false;
        }

        // The universal property: for any admissible inputs that do not revert, the correct contract returns true.
        // We assert that the observed return (ok) is true. The mutant that returns false will fail this for some inputs.
        assertTrue(ok);
    }
}

// Adversarial helper: accepts low-level call with selector transferFrom(address,address,uint256)
contract AcceptAll {
    // Provide a fallback matching the low-level call signature; it doesn't need to revert.
    fallback() external payable {
        // simply accept the call and do nothing, so the caller's require(_s) succeeds
    }
}

