pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: from (the account that should be forwarded as first arg),
    // potentialTo (one of the tos), and v amount; caddress is the callee we route through a helper
    function testFuzz_property(address from, address potentialTo, uint256 v) public {
        // keep wide domain but avoid zero-length tos: we'll construct a single-element array
        vm.assume(from != address(0));
        vm.assume(potentialTo != address(0));

        // deploy an adversarial callee that only accepts calls whose first address equals `from`
        CalleeChecker callee = new CalleeChecker(from);

        address[] memory tos = new address[](1);
        tos[0] = potentialTo;

        // We will call c.transfer(from, address(callee), tos, v) and observe whether it reverts/succeeds.
        bool ok;
        try c.transfer(from, address(callee), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: the correct contract always forwards `from` as the first address to the external call,
        // so the call to our CalleeChecker (which requires its first arg == from) will succeed for all inputs.
        // The mutant swaps the two addresses and thus will fail for some inputs (when potentialTo != from).
        // Assert that the call succeeded (reference holds for all inputs); the mutant will make this fail for some fuzz inputs.
        assertTrue(ok);
    }
}

// Adversarial callee: expects the first address argument to match `expectedFirst` or it reverts.
contract CalleeChecker {
    address public expectedFirst;
    constructor(address _expectedFirst) { expectedFirst = _expectedFirst; }

    // The tested contract uses low-level call with selector transferFrom(address,address,uint256)
    // We'll implement that selector and check the first address argument.
    function transferFrom(address a, address b, uint256) external {
        require(a == expectedFirst, "first address mismatch");
        // succeed otherwise
    }

    // fallback to accept direct low-level selector encoding too
    fallback() external payable {
        // decode calldata: selector (4 bytes) + args; try to extract first address
        if (msg.data.length >= 4 + 32) {
            // skip selector
            bytes memory data = msg.data[4:];
            // first arg is at data[0:32]
            address a;
            assembly { a := mload(add(data, 32)) }
            if (a != expectedFirst) revert("first address mismatch");
        }
    }
}

